abstract class SetMarkupItemConsideredAction : DockingAction {

	VTController controller;

	SetMarkupItemConsideredAction(VTController controller, string actionName) : base(actionName, VTPlugin.OWNER)
    {
		this.controller = controller;
	}

	abstract VTMarkupItemConsideredStatus getTagType();

	/* @Override */
	public void actionPerformed(ActionContext context) {
		VTSession session = controller.getSession();
		List<VTMarkupItem> markupItems = controller.getMarkupItems(context);
		TagMarkupItemTask task = new TagMarkupItemTask(session, markupItems, getTagType());
		task.addTaskListener(new _Anon_TaskListener_1());
		controller.runVTTask(task);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		List<VTMarkupItem> markupItems = controller.getMarkupItems(context);

		if (markupItems.size() == 0) {
			return false;
		}

		VTMarkupItemStatus thisActionsStatus = getTagType().getMarkupItemStatus();

		foreach (VTMarkupItem markupItem in markupItems) {
			VTMarkupItemStatus status = markupItem.getStatus();
			if (!markupItem.canApply() || status.equals(thisActionsStatus)) {
				return false;
			}
		}

		return true;
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		List<VTMarkupItem> markupItems = controller.getMarkupItems(context);

		if (markupItems.size() == 0) {
